const items=[{name:'Bebidas',word:'BEBIDAS',image:'summer',title:'Para llevar contigo.',copy:'Bebidas, reuniones y días que no se detienen.',detail:'Explora termos, vasos y cubetas. Elige el tipo de producto y solicita las opciones disponibles para tu campaña.'},{name:'Textil',word:'TEXTIL',image:'neutral',title:'Tu identidad, en movimiento.',copy:'Objetos cotidianos que se vuelven parte del equipo.',detail:'Bolsas, gorras y accesorios para acompañar a tu equipo. Consulta los materiales y las técnicas de personalización.'},{name:'Regalos',word:'REGALOS',image:'christmas',title:'El detalle que se queda.',copy:'Una selección para agradecer y celebrar.',detail:'Un punto de partida para tu regalo corporativo. La composición final se define según disponibilidad, presupuesto y cantidad.'},{name:'Tecnología',word:'CONECTA',image:'halloween',title:'Otra forma de conectar.',copy:'Accesorios y detalles para tus próximas ideas.',detail:'Descubre alternativas de tecnología y accesorios en los catálogos. Esta escena es una referencia conceptual.'}];
const $=s=>document.querySelector(s),orbit=$('#orbit'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let active=0,paused=reduced.matches,start=null,dragged=false;
items.forEach((item,i)=>{const b=document.createElement('button');b.className='object';b.innerHTML=`<img src="/assets/scene-${item.image}-480.webp" alt="Montaje conceptual de ${item.name}" width="480" height="480" draggable="false"><span>${item.name.toUpperCase()}</span>`;b.setAttribute('aria-label',`Seleccionar ${item.name}`);b.addEventListener('click',()=>{if(!dragged)select(i)});orbit.append(b);const m=document.createElement('button');m.className='map-node';m.innerHTML=`<small>0${i+1} / COLECCIÓN</small><img src="/assets/scene-${item.image}-480.webp" alt="" width="480" height="480"><b>${item.name} ↗</b>`;m.addEventListener('click',()=>{select(i);$('#map').close();});$('#map-grid').append(m);});
function layout(){const radius=innerWidth<700?innerWidth*.40:Math.min(innerWidth*.30,380);document.querySelectorAll('.object').forEach((b,i)=>{const angle=(i-active)*Math.PI/2;const depth=Math.cos(angle);b.style.setProperty('--x',`${Math.sin(angle)*radius}px`);b.style.setProperty('--y',`${-55*(1-depth)}px`);b.style.setProperty('--scale',i===active?'1.16':String(.53+(depth+1)*.08));b.style.setProperty('--opacity',i===active?'1':'.55');b.style.setProperty('--z',String(Math.round((depth+1)*10)));b.setAttribute('aria-pressed',String(i===active));});}
function select(i){active=(i+items.length)%items.length;const item=items[active];layout();$('#title').textContent=item.title;$('#description').textContent=item.copy;$('#index').textContent=`0${active+1} / 04`;$('.kinetic').textContent=item.word;$('.kinetic').classList.remove('enter');if(!paused){void $('.kinetic').offsetWidth;$('.kinetic').classList.add('enter');}$('#announcement').textContent=`Colección ${item.name}`;}
$('#previous').addEventListener('click',()=>select(active-1));$('#next').addEventListener('click',()=>select(active+1));orbit.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();select(active+(e.key==='ArrowRight'?1:-1));}});
orbit.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={x:e.clientX,y:e.clientY};dragged=false;});window.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){dragged=true;select(active+(dx<0?1:-1));setTimeout(()=>dragged=false,0);}});window.addEventListener('pointercancel',()=>{start=null;});
document.querySelectorAll('[data-world]').forEach(b=>{if(b.tagName!=='BUTTON')return;b.addEventListener('click',()=>{document.body.dataset.world=b.dataset.world;document.querySelectorAll('.worlds button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#announcement').textContent=`Entorno: ${b.textContent}`;});});
function motion(){document.body.classList.toggle('paused',paused);$('#motion').setAttribute('aria-pressed',String(!paused));$('#motion').textContent=paused?'Activar movimiento':'Pausar movimiento';}$('#motion').addEventListener('click',()=>{paused=!paused;motion();});reduced.addEventListener('change',()=>{paused=reduced.matches;motion();});
$('#map-open').addEventListener('click',()=>$('#map').showModal());$('#details-open').addEventListener('click',()=>{const item=items[active];$('#detail-image').src=`/assets/scene-${item.image}-960.webp`;$('#detail-image').alt=`Montaje conceptual: ${item.name}`;$('#detail-title').textContent=item.name;$('#detail-copy').textContent=item.detail;$('#details').showModal();});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));window.addEventListener('resize',layout);select(0);motion();
